<div><div    x-data="{        requestId: 0,        visibleCount: 10,        loading: false,        draftKey: 'xlap.suncatcher-two.add-product-design.draft',        draftTimer: null, lastPersisted: '',        draftSnapshot() { return { keyword: this.$wire.keyword, step: this.$wire.step, workflowStep: this.$wire.workflowStep, personPrompts: this.$wire.personPrompts, personUrls: this.$wire.personUrls, researchResults: this.$wire.researchResults, selectedResearchUrls: this.$wire.selectedResearchUrls, scrapedCompetitors: this.$wire.scrapedCompetitors, competitorListing: this.$wire.competitorListing, imageLink: this.$wire.imageLink, selectedImageUrl: this.$wire.selectedImageUrl, sourceImageUrl: this.$wire.sourceImageUrl, mainImageUrl: this.$wire.mainImageUrl, mainImagePrompt: this.$wire.mainImagePrompt, draftWorkflow: this.$wire.draftWorkflow }; },        saveDraft() { const snapshot = this.draftSnapshot(); const serialized = JSON.stringify(snapshot); localStorage.setItem(this.draftKey, serialized); if (serialized !== this.lastPersisted) { this.lastPersisted = serialized; this.$wire.persistDraft(snapshot); } },        async restoreDraft() { const raw = localStorage.getItem(this.draftKey); if (raw) { try { await this.$wire.restoreDraft(JSON.parse(raw)); } catch (error) { localStorage.removeItem(this.draftKey); } } },        send(type, payload = {}) {            return new Promise((resolve, reject) => {                const id = `${Date.now()}-${++this.requestId}`;                const handler = (event) => {                    if (event.data?.source !== 'AMZ_RESEARCH_EXTENSION' || event.data?.requestId !== id) return;                    window.removeEventListener('message', handler);                    event.data.response?.ok ? resolve(event.data.response) : reject(new Error(event.data.response?.error || 'Extension khong phan hoi.'));                };                window.addEventListener('message', handler);                window.postMessage({ source: 'XLAP_SUNCATCHER_TWO', requestId: id, message: { type, ...payload } }, '*');                window.setTimeout(() => { window.removeEventListener('message', handler); reject(new Error('Khong ket noi duoc AMZ Research extension. Hay reload extension tai chrome://extensions va tai lai trang.')); }, 180000);            });        },        async research() {            this.loading = true;            try { const result = await this.send('AMZ_RESEARCH_KEYWORD', { platform: 'amazon', keyword: this.$wire.keyword }); this.$wire.setResearchResults(result.results || []); }            catch (error) { this.$wire.setError(error.message); }            finally { this.loading = false; }        },        async continueAndScrape() {            if (this.$wire.selectedResearchUrls.length !== 5) return;            await this.$wire.continueToScrape();            await this.scrape();        },        async scrape() {            this.loading = true;            try { const urls = JSON.parse(JSON.stringify(this.$wire.selectedResearchUrls || [])); const result = await this.send('AMZ_SCRAPE_SELECTED', { urls }); this.$wire.setScrapedResults(result.jobs || []); }            catch (error) { this.$wire.setError(error.message); }            finally { this.loading = false; }        }    }"    x-init="await restoreDraft(); draftTimer = window.setInterval(() => saveDraft(), 500)"    x-on:suncatcher-two-draft-clear.window="localStorage.removeItem(draftKey); window.clearInterval(draftTimer)"    x-on:suncatcher-two-scrape-data-cleared.window="localStorage.removeItem(draftKey)"    x-on:keydown.escape.window="{{ $embedded ? '' : '$wire.close()' }}"    class="{{ $embedded ? 'rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900' : 'fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-gray-900/50 p-4' }}"    @if (! $embedded) role="dialog" aria-modal="true" @endif>    @if (! $embedded)        <button type="button" class="fixed inset-0" wire:click="close" aria-label="C